{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "Despite advances made in curbing the global malaria burden since the 2000s, progress has stalled, in part due to a plateauing of the financing available to implement needed interventions. In 2020, approximately 3.3 billion USD was invested globally for malaria interventions, falling short of the targeted 6.8 billion USD set by the GTS, increasing the financial gap between desirable and actual investment.",
      "reason": "The abstract background describes the current state of knowledge (progress stalling, financing gap) but a dedicated Introduction section with a fuller account of existing knowledge and uncertainties was not retrieved."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "Models for malaria control optimization are used to disentangle the most efficient interventions or packages of interventions for inherently constrained budgets. This systematic review aimed to identify and characterise models for malaria control optimization for resource allocation in limited resource settings and assess their strengths and limitations.",
      "reason": "The need for the review is implied by the financing gap and the role of optimization models, but the rationale is only briefly stated in the abstract; no dedicated Introduction rationale text was retrieved."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence discusses prior or existing systematic reviews on this topic or justifies an update/replication; the Introduction section was not available in the evidence."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although the review covers interventions (ITNs, IRS, SMC, case management), no retrieved text describes a proposed mechanism of action for these interventions."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence mentions a logic model or hypothesised relationships between intervention components and outcomes."
    }
  ],
  "confidence": 60
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The research question for this review was ' Are there English-language publications in peer-reviewed scientific journals describing how models have been used to allocate resources for malaria interventions in limited resource settings?' The main aim of this review was to identify and characterize models for malaria control optimization for resource allocation in malaria control and elimination settings and to identify their strengths and limitations.",
      "reason": "The review explicitly states both a research question and the main aim/objectives; the abstract (text_2) restates the aim: 'This systematic review aimed to identify and characterise models for malaria control optimization... and assess their strengths and limitations.'"
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of optimization models for malaria resource allocation, not a review of intervention effects; no planned intervention comparisons are reported and PICO-style comparisons do not apply to the stated objectives."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Studies containing an optimization model (mathematical or statistical); (6) All studies with human Plasmodium species; (7) Studies with two or more interventions; (8) Cost data were used in combination with the model outputs; (9) Outcomes/health benefits were clearly stated and/or measured.",
      "reason": "Inclusion criteria specify eligible study designs (optimization models), population (human Plasmodium, any subgroup), setting (any geographical region), interventions (two or more), and outcome requirements. No explicit follow-up requirement, but this is not essential for modelling studies."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "(1) Were scientific peer-reviewed journals written in English; (2) Were published before 30th June 2024",
      "reason": "Report characteristics are specified: publication status (peer-reviewed, with editorials, pre-prints, grey literature etc. excluded per text_9), language (English), and dissemination date (before 30 June 2024)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_9",
      "quote": "The following records were excluded: (1) Editorials, commentaries, opinion papers, conference abstracts, media reports, letters, bulletins, pre-prints, grey literature; (2) Non-English language studies; (3) Systematic reviews, meta-analyses.",
      "reason": "The review does not distinguish exclusion because outcomes were not measured from exclusion because outcome results were not reported; exclusion reasons listed are publication types, language, and review type only."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": "text_10",
      "quote": "A narrative synthesis of the study characteristics was performed.",
      "reason": "A narrative synthesis was performed and data extraction fields are listed, but no explicit groups for synthesis are specified or linked to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": "text_7",
      "quote": "Each record in the search were included if they met all of the following criteria",
      "reason": "Notable restrictions (e.g., English-only, two or more interventions, cost data requirement) are stated but no rationales for these restrictions are provided anywhere in the retrieved evidence."
    }
  ],
  "confidence": 88
}

